SELECT p.id, pr.name as project, p.name, p.describe, p.version_id as version, a.nickname as creator, DATE_FORMAT(p.changed_on, '%Y-%m-%d %H:%i:%s') as modified, p.expand, ae.name as aiExperimentName FROM pipeline p LEFT JOIN project pr ON p.project_id = pr.id LEFT JOIN ab_user a ON p.created_by_fk = a.id LEFT JOIN ai_experiment ae ON p.ai_experiment_id = ae.id
AND p.id = #{id}
AND p.name LIKE CONCAT('%', #{name}, '%')
AND p.describe LIKE CONCAT('%', #{describe}, '%')
AND pr.name = #{namespace}
AND a.nickname LIKE CONCAT('%', #{creator}, '%')
AND p.ai_experiment_id = #{aiExperimentId}
ORDER BY p.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT p.id)
FROM pipeline p
LEFT JOIN project pr ON p.project_id = pr.id
LEFT JOIN ab_user a ON p.created_by_fk = a.id


        AND p.id = #{id}


        AND p.name LIKE CONCAT('%', #{name}, '%')


        AND p.describe LIKE CONCAT('%', #{describe}, '%')


        AND pr.name = #{namespace}


        AND a.nickname LIKE CONCAT('%', #{creator}, '%')


        AND p.ai_experiment_id = #{aiExperimentId}
